import React from 'react';
import { useDraggable } from '@dnd-kit/core';
import './ProjectCard.css';

export function ProjectCard({ project, onRemove }) {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id: project.id,
    data: { projectId: project.id }
  });

  const style = {
    transform: transform ? `translate3d(${transform.x}px, ${transform.y}px, 0)` : undefined,
    opacity: isDragging ? 0.5 : 1,
    zIndex: isDragging ? 100 : 'auto'
  };

  const handleRemove = (e) => {
    e.stopPropagation();
    if (window.confirm(`Удалить проект "${project.title}"?`)) {
      onRemove(project.id);
    }
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...listeners}
      {...attributes}
      className={`project-card ${isDragging ? 'dragging' : ''}`}
    >
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <span>{project.title}</span>
        <button onClick={handleRemove} className="remove-project-btn" title="Удалить проект">✕</button>
      </div>
    </div>
  );
}