import React, { useState } from 'react';
import { DndContext } from '@dnd-kit/core';
import { EmployeesPanel } from './components/EmployeesPanel';
import { ProjectsPool } from './components/ProjectsPool';
import TeamStatsSidebar from './components/TeamStatsSidebar';
import { useAssignments } from './hooks/useAssignments';
import { useFirebaseEmployees } from './hooks/useFirebaseEmployees';
import { useFirebaseProjects } from './hooks/useFirebaseProjects';
import { useFirebaseTeams } from './hooks/useFirebaseTeams';
import './App.css';

function App() {
  const {
    employees,
    addEmployee,
    removeEmployee,
    updateEmployeeTeam,
    updateEmployeeStartDate,
    updateEmployeePhone,
    loading: empLoading
  } = useFirebaseEmployees();
  const { projects, addProject, removeProject, loading: projLoading } = useFirebaseProjects();
  const { teams, addTeam, removeTeam, loading: teamsLoading } = useFirebaseTeams();
  const { assignments, removeAssignment, handleDragEnd, loading: assignLoading } = useAssignments();

  const [teamFilter, setTeamFilter] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  if (empLoading || projLoading || teamsLoading || assignLoading) {
    return <div className="loading">Загрузка...</div>;
  }

  return (
    <DndContext onDragEnd={handleDragEnd}>
      <div className="app-container three-columns">
        <EmployeesPanel
          employees={employees}
          teams={teams}
          assignments={assignments}
          projects={projects}
          onRemoveAssignment={removeAssignment}
          onAddEmployee={addEmployee}
          onRemoveEmployee={removeEmployee}
          onUpdateEmployeeTeam={updateEmployeeTeam}
          onUpdateEmployeeStartDate={updateEmployeeStartDate}
          onUpdateEmployeePhone={updateEmployeePhone}
          onAddTeam={addTeam}
          onRemoveTeam={removeTeam}
          teamFilter={teamFilter}
          setTeamFilter={setTeamFilter}
          searchTerm={searchTerm}
          setSearchTerm={setSearchTerm}
        />
        <ProjectsPool
          projects={projects}
          onAddProject={addProject}
          onRemoveProject={removeProject}
        />
        <TeamStatsSidebar teams={teams} employees={employees} />
      </div>
    </DndContext>
  );
}

export default App;