import { useState, useEffect } from 'react';
import { db } from '../firebase';
import { collection, onSnapshot, addDoc, deleteDoc, doc, query, orderBy, where, getDocs, updateDoc } from 'firebase/firestore';

export function useFirebaseEmployees() {
  const [employees, setEmployees] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const q = query(collection(db, 'employees'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setEmployees(data);
      setLoading(false);
    }, (error) => {
      console.error("Ошибка загрузки сотрудников:", error);
      setLoading(false);
    });
    return () => unsubscribe();
  }, []);

  const addEmployee = async (name) => {
    try {
      await addDoc(collection(db, 'employees'), {
        name,
        teamId: null,
        startDate: null,
        phone: null,
        createdAt: new Date().toISOString()
      });
    } catch (error) {
      console.error("Ошибка добавления сотрудника:", error);
    }
  };

  const removeEmployee = async (id) => {
    try {
      await deleteDoc(doc(db, 'employees', id));
      const q = query(collection(db, 'assignments'), where('employeeId', '==', id));
      const snapshot = await getDocs(q);
      const deletePromises = snapshot.docs.map(docSnapshot => deleteDoc(doc(db, 'assignments', docSnapshot.id)));
      await Promise.all(deletePromises);
    } catch (error) {
      console.error("Ошибка удаления сотрудника:", error);
    }
  };

  const updateEmployeeTeam = async (employeeId, teamId) => {
    try {
      await updateDoc(doc(db, 'employees', employeeId), { teamId });
    } catch (error) {
      console.error("Ошибка обновления команды:", error);
    }
  };

  const updateEmployeeStartDate = async (employeeId, startDate) => {
    try {
      await updateDoc(doc(db, 'employees', employeeId), { startDate });
    } catch (error) {
      console.error("Ошибка обновления даты начала работы:", error);
    }
  };

  const updateEmployeePhone = async (employeeId, phone) => {
    try {
      await updateDoc(doc(db, 'employees', employeeId), { phone });
    } catch (error) {
      console.error("Ошибка обновления номера телефона:", error);
    }
  };

  return { employees, addEmployee, removeEmployee, updateEmployeeTeam, updateEmployeeStartDate, updateEmployeePhone, loading };
}