import React, { useEffect, useState } from 'react';
import { useDroppable } from '@dnd-kit/core';
import { ProjectChip } from './ProjectChip';
import './EmployeeCard.css';

function computeTenure(startDate) {
  if (!startDate) return null;
  const start = new Date(startDate);
  const now = new Date();
  const years = now.getFullYear() - start.getFullYear();
  const months = now.getMonth() - start.getMonth();
  let totalMonths = years * 12 + months;
  if (now.getDate() < start.getDate()) totalMonths--;
  if (totalMonths < 0) totalMonths = 0;
  const y = Math.floor(totalMonths / 12);
  const m = totalMonths % 12;
  if (y > 0) return `${y} г ${m} мес`;
  return `${m} мес`;
}

export function EmployeeCard({
  employee,
  assignedProjects,
  onRemoveAssignment,
  onRemoveEmployee,
  teams,
  onUpdateEmployeeTeam,
  onUpdateEmployeeStartDate,
  onUpdateEmployeePhone
}) {
  const { setNodeRef, isOver } = useDroppable({
    id: employee.id,
    data: { employeeId: employee.id }
  });

  const [startDate, setStartDate] = useState(employee.startDate || '');
  const [phone, setPhone] = useState(employee.phone || '');

  // Синхронизируем значение, когда пришло из Firestore
  useEffect(() => {
    setPhone(employee.phone || '');
  }, [employee.phone]);

  // Дебаунс авто-сохранения телефона, чтобы не слать запрос на каждый символ
  useEffect(() => {
    if (!onUpdateEmployeePhone) return;
    const normalized = phone.trim();
    const valueToSave = normalized.length > 0 ? normalized : null;
    const current = employee.phone || null;
    if (valueToSave === current) return;

    const t = setTimeout(() => {
      onUpdateEmployeePhone(employee.id, valueToSave);
    }, 600);

    return () => clearTimeout(t);
  }, [phone, employee.id, employee.phone, onUpdateEmployeePhone]);

  const handleRemoveEmployee = () => {
    if (window.confirm(`Удалить сотрудника ${employee.name}?`)) {
      onRemoveEmployee(employee.id);
    }
  };

  const handleTeamChange = (e) => {
    const newTeamId = e.target.value === '' ? null : e.target.value;
    onUpdateEmployeeTeam(employee.id, newTeamId);
  };

  const handleStartDateChange = (e) => {
    const date = e.target.value;
    setStartDate(date);
    onUpdateEmployeeStartDate(employee.id, date);
  };

  const tenure = computeTenure(employee.startDate);

  return (
    <div
      ref={setNodeRef}
      className={`employee-card ${isOver ? 'drag-over' : ''}`}
    >
      <div className="employee-header">
        <h4>{employee.name}</h4>
        <div className="employee-controls">
          <select
            className="team-select"
            value={employee.teamId || ''}
            onChange={handleTeamChange}
          >
            <option value="">Без команды</option>
            {teams.map(team => (
              <option key={team.id} value={team.id}>{team.name}</option>
            ))}
          </select>
          <button onClick={handleRemoveEmployee} className="remove-employee-btn" title="Удалить сотрудника">✕</button>
        </div>
      </div>

      <div className="employee-tenure">
        <label>Дата начала работы: </label>
        <input
          type="date"
          value={startDate}
          onChange={handleStartDateChange}
        />
        {tenure && <span className="tenure-value"> (Стаж: {tenure})</span>}
      </div>

      <div className="employee-phone">
        <label>Телефон: </label>
        <input
          type="tel"
          value={phone}
          onChange={(e) => setPhone(e.target.value)}
          placeholder="+7 ..."
        />
      </div>

      <div className="projects-list">
        {assignedProjects.map(project => (
          <ProjectChip
            key={project.id}
            project={project}
            employeeId={employee.id}
            onRemove={onRemoveAssignment}
          />
        ))}
        {assignedProjects.length === 0 && (
          <span className="empty-projects">Нет проектов</span>
        )}
      </div>
    </div>
  );
}